// Client-only guards. Embedded into n8n Code nodes; no network or credentials.
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const fail = (status, code) => ({ business_ok: false, status, error_code: code, summary: {} });
const publicLink = value => typeof value === 'string' && value.length <= 2048 && /^https:\/\/[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?(?:\/[^\s]*)?$/.test(value) ? value : null;

function errorState(value, depth = 0) {
  if (depth > 32) return 'INVALID';
  if (value === null || typeof value !== 'object') return 'NONE';
  if (Object.hasOwn(value, 'isError') && typeof value.isError !== 'boolean') return 'INVALID';
  if (Object.hasOwn(value, 'error') || value.isError === true) return 'ERROR';
  let state = 'NONE';
  for (const child of Object.values(value)) {
    const next = errorState(child, depth + 1);
    if (next === 'INVALID') return next;
    if (next === 'ERROR') state = next;
  }
  return state;
}

function unwrap(items) {
  if (!Array.isArray(items) || items.length !== 1 || !object(items[0]?.json)) return { failure: fail('INVALID_PAYLOAD', 'EXPECTED_ONE_NATIVE_RESULT') };
  const raw = items[0].json;
  const state = errorState(raw);
  if (state !== 'NONE') return { failure: fail(state === 'ERROR' ? 'BUSINESS_ERROR' : 'INVALID_PAYLOAD', 'NATIVE_RESULT_REJECTED') };
  // Native MCP Client 1.1 returned structuredContent in the dated acceptance.
  // Do not scrape text content or guess alternative wrappers on a changed client.
  if (!object(raw.structuredContent)) return { failure: fail('INVALID_PAYLOAD', 'STRUCTURED_CONTENT_REQUIRED') };
  return { data: raw.structuredContent };
}

function normalizeConnection(items) {
  const result = unwrap(items);
  if (result.failure) return result.failure;
  const d = result.data;
  const required = ['agent', 'connection', 'plan', 'usage', 'limits', 'postAllowance', 'costRules', 'quotaPolicy', 'upgrade', 'dataUse'];
  if (required.some(k => !object(d[k])) || d.connection.writes !== false || typeof d.agent.id !== 'string' || !d.agent.id ||
      typeof d.plan.infoClass !== 'string' || !/^[A-Z0-9_]{1,80}$/.test(d.plan.infoClass)) return fail('INVALID_PAYLOAD', 'INVALID_CONNECTION');
  if (typeof d.usage.subject !== 'string' || !d.usage.subject.trim() || d.usage.subject.length > 80) return fail('INVALID_PAYLOAD', 'INVALID_METERING_SUBJECT');
  const remaining = {};
  for (const period of ['daily', 'monthly']) {
    const n = d.usage[period]?.remaining;
    const limit = d.usage[period]?.limit;
    if (!Number.isSafeInteger(n) || n < 0 || !Number.isSafeInteger(limit) || limit < 0) return fail('INVALID_PAYLOAD', 'INVALID_ALLOWANCE');
    remaining[period] = n;
  }
  if (d.costRules.get_connection !== 0) return fail('POLICY_CHANGED', 'CONNECTION_COST_CHANGED');
  return { business_ok: true, status: 'CONNECTION_READY', error_code: '', summary: { readonly: true, planClass: d.plan.infoClass, remaining } };
}

function prepareRead(items, config) {
  const connection = normalizeConnection(items);
  if (!connection.business_ok) return { ...connection, can_read: false };
  if (!object(config) || typeof config.skill_id !== 'string' || !/^[a-zA-Z0-9_-]{1,200}$/.test(config.skill_id)) return { ...fail('INVALID_INPUT', 'INVALID_SKILL_ID'), can_read: false };
  const data = items[0].json.structuredContent;
  // This candidate admits exactly one detail page, only at its advertised cost.
  // A future price needs a reviewed candidate, never an implicit higher budget.
  if (data.costRules.get_network_item?.perPage !== 1) return { ...fail('POLICY_CHANGED', 'DETAIL_COST_CHANGED'), can_read: false };
  if (connection.summary.remaining.daily < 1 || connection.summary.remaining.monthly < 1) return { ...fail('QUOTA_UNAVAILABLE', 'NO_DETAIL_ALLOWANCE'), can_read: false };
  return { ...connection, status: 'DETAIL_READ_READY', can_read: true, skill_id: config.skill_id, planned_info_units: 1 };
}

function inspectSkill(items, config) {
  const result = unwrap(items);
  if (result.failure) return result.failure;
  const { item, usage } = result.data;
  if (!object(item) || item.kind !== 'SKILL' || item.id !== config.skill_id || typeof item.title !== 'string' || !item.title ||
      typeof item.version !== 'string' || !item.version || typeof item.reviewStatus !== 'string' ||
      !Array.isArray(item.permissions) || item.permissions.some(p => typeof p !== 'string') ||
      typeof item.license !== 'string' || !object(usage) || usage.costUnits !== 1) return fail('INVALID_PAYLOAD', 'INVALID_SKILL_DETAIL');
  // These fields are data, never installation instructions or executable code.
  return { business_ok: true, status: 'SKILL_EVIDENCE_READ', error_code: '', summary: {
    id: item.id, title: item.title, version: item.version, evidenceLevel: item.reviewStatus,
    sourceUrl: publicLink(item.sourceUrl), canonicalUrl: publicLink(item.canonicalUrl),
    declaredPermissions: item.permissions, declaredLicense: item.license,
    trustLevel: 'UNTRUSTED_NETWORK_CONTENT', reported_info_units: usage.costUnits,
    next_step: 'Review the Skill source, permissions and host compatibility. Installation or SDK/API writes require separate authorization.',
    installed: false, runtimeVerifiedByThisWorkflow: false,
  } };
}

function finishReceipt(afterItems, beforeItems, prepared, evidence) {
  const after = normalizeConnection(afterItems);
  if (!after.business_ok) return { ...fail('METERING_UNKNOWN', 'AFTER_CONNECTION_INVALID'), evidence };
  const before = normalizeConnection(beforeItems);
  if (!before.business_ok || !prepared.can_read || !object(evidence) || typeof evidence.business_ok !== 'boolean') return fail('INVALID_PAYLOAD', 'RECEIPT_INPUT_INVALID');
  const a = afterItems[0].json.structuredContent, b = beforeItems[0].json.structuredContent;
  if (a.agent.id !== b.agent.id || a.usage.subject !== b.usage.subject || a.plan.infoClass !== b.plan.infoClass) return { ...fail('METERING_UNKNOWN', 'SUBJECT_CHANGED'), evidence };
  for (const period of ['daily', 'monthly']) {
    if (typeof a.usage[period].resetsAt !== 'string' || a.usage[period].resetsAt !== b.usage[period].resetsAt || a.usage[period].limit !== b.usage[period].limit) return { ...fail('METERING_UNKNOWN', 'WINDOW_CHANGED'), evidence };
  }
  const daily = before.summary.remaining.daily - after.summary.remaining.daily;
  const monthly = before.summary.remaining.monthly - after.summary.remaining.monthly;
  const consistent = daily === 1 && monthly === 1 && evidence.business_ok;
  return { business_ok: Boolean(evidence.business_ok), status: consistent ? 'SKILL_EVIDENCE_AND_BALANCE_OBSERVED' : 'SKILL_READ_METERING_UNKNOWN',
    error_code: consistent ? '' : 'ALLOWANCE_DELTA_OR_EVIDENCE_UNCONFIRMED', evidence,
    metering: { dailyAllowanceDelta: daily, monthlyAllowanceDelta: monthly, reportedDetailUnits: evidence.summary?.reported_info_units ?? null,
      exclusiveUseAssumed: false, chargeAttribution: 'NOT_PROVEN_BY_SHARED_BALANCE', cashPaymentTested: false },
    retry: false };
}

return [{json: prepareRead($input.all(), $("Choose Skill").first().json)}];

